      "target": "ecr",
      "risk_class": "critical",
      "rollback": {
        "trigger": "push fails",
        "action": "retag images back to docker hub",
        "safety_guard": "verify docker hub image availability"
      },
      "verification": {
        "what": "push success",
        "how": "check push logs",
        "expected": "All images pushed successfully"
      },
      "preconditions": [
        {
          "description": "Images have been retagged",
          "fact": "images_retagged",
          "established_by": "retag_images"
        }
      ]
    },
    {
      "id": "update_manifests",
      "description": "Update deployment and StatefulSet manifests to reference new ECR URI",
      "action": "update",
      "target": "k8s_manifests",
      "risk_class": "high",
      "rollback": {
        "trigger": "update fails",
        "action": "restore old manifests",
        "safety_guard": "verify previous manifests"
      },
      "verification": {
        "what": "manifest correctness",
        "how": "kubectl diff",
        "expected": "No changes not related to ECR"
      },
      "preconditions": [
        {
          "description": "Images are pushed to ECR",
          "fact": "images_pushed",
          "established_by": "push_images"
        }
      ]
    },
    {
      "id": "rolling_restart",
      "description": "Trigger a rolling restart for the services",
      "action": "restart",
      "target": "k8s_deployments",
      "risk_class": "critical",
      "rollback": {
        "trigger": "restart fails",
        "action": "revert to old deployment",
        "safety_guard": "verify old deployment health"
      },
      "verification": {
        "what": "service availability",
        "how": "kubectl get pods",
        "expected": "All pods in Running state"
      },
      "preconditions": [
        {
          "description": "Manifests are updated",
          "fact": "manifests_updated",
          "established_by": "update_manifests"
        }
      ]
    },
    {
      "id": "verify_services",
      "description": "Verify each service pod can pull from ECR and serves traffic normally",
      "action": "verify",
      "target": "k8s_services",
      "risk_class": "critical",
      "rollback": {
        "trigger": "verification fails",
        "action": "scale down and revert to old deployments",
        "safety_guard": "services available on previous images"
      },
      "verification": {
        "what": "service health",
        "how": "access services and check responses",
        "expected": "All services serve traffic normally"
      },
      "preconditions": [
        {
          "description": "Rolling restart completed successfully",
          "fact": "pods_running",
          "established_by": "rolling_restart"
        }
      ]
    }
  ],
  "dependencies": [
    {
      "from_task": "pull_images",
      "to_task": "retag_images",
      "kind": "hard"
    },
    {
      "from_task": "retag_images",
      "to_task": "push_images",
      "kind": "hard"
    },
    {
      "from_task": "push_images",
      "to_task": "update_manifests",
      "kind": "hard"
    },
    {
      "from_task": "update_manifests",
      "to_task": "rolling_restart",
      "kind": "hard"
    },
    {
      "from_task": "rolling_restart",
      "to_task": "verify_services",
      "kind": "hard"
    }
  ],
  "branches": {
    "id": "rollback_branch",
    "kind": "fan_out",
    "tasks": [
      "push_images",
      "update_manifests",
      "rolling_restart",
      "verify_services"
    ],
    "join": "quorum"
  }
}

